pfUI.octoNotes = {
  { "1.2.17", {
    { "New flight launcher", "an arcade marquee - a lit OCTO ARCADE sign with Darkmoon tickets, chasing bulbs and a sweep of light, a blinking INSERT COIN line, and three game cards (Quiz, Aim Trainer, High Scores) with glowing icons and live info: question count or your best streak, your top aim score, how many scores are on the board. It slides in, can be dragged anywhere, and remembers where you put it." },
    { "Flight bar", "the feather at the end of the bar no longer sits in a black square - it glows on the bar by itself." },
  } },
  { "1.2.16", {
    { "Aim trainer, arcade style", "modes on their own row (pick any mode at any time - a running round just stops), big stat panels, a timer bar that runs down, a scanline screen with glowing corners, 3-2-1-GO!, hit bursts, combo callouts (ON FIRE! x20, GODLIKE x50, BULLSEYE!, INTERRUPTED!), and a results card with a grade from S to D and a flashing NEW HIGH SCORE!" },
    { "Scores across the realm", "pfUI joins a hidden OctoArcade channel and says one short line with your bests once per login; everyone on the realm with pfUI Octo reads it into their Scores. You never see the channel in chat. Switch it off in Minigames Scores." },
  } },
  { "1.2.15", {
    { "OctoArcade - minigames for flights", "a small launcher pops up when a flight starts (or the game you pick opens by itself), and closes when you land. Also /arcade, /quiz, /aim, key bindings, and Quality of Life Minigames. Switch it off there or in the QoL Helpers list. New files: restart the game fully once." },
    { "Classic quiz", "660 questions of our own on lore, characters, places, dungeons, raids, classes, professions, items, PvP and the world - 10 categories you can switch on or off, a short \"did you know\" after many answers, streaks, and an optional timer." },
    { "Aim trainer, six modes", "Gridshot, Hexakill, Reflex, Precision (centre hits score more), Tracking (keep the mouse on a moving target) and Kick! (click the casters before their cast bar fills). Targets wear the other faction's faces, creatures, class pictures, raid marks or spell icons; results show accuracy, reaction time and best combo." },
    { "Scores shared between players", "bests go to your guild, group and battleground, and boards fill from the players they have met too." },
  } },
  { "1.2.14", {
    { "The Group Finder in pfUI's look", "OctoWoW's own group finder (Group Browser and Dungeon Finder), its role check, the \"your group is ready\" pop-up and the ready check window with the role circles now use pfUI's dark panels, buttons, tabs and bars instead of the game's wooden frames. The dungeon and role pictures stay. A new file, so restart the game fully (not just /reload)." },
  } },
  { "1.2.13", {
    { "Pick your parts when you install", "the installer has a new \"Which parts do you want?\" step. Click tiles to turn Meters, Combat Text, OctoDoTs, OctoRinse, the Auction House and 17 more on or off, or use All on / All off. Already installed? Run /pfui install to see it." },
    { "A tidier Send tab", "the money controls have their own panel, so nothing overlaps. A line under the amount says what will happen (\"They pay 5g for each of the 3 mails\"), and Clear and a bigger Send button sit in their own column." },
  } },
  { "1.2.12", {
    { "Breakdown reports work from every tab", "reporting the Summary or Deaths tab (a death log, for example) no longer gives a Lua error." },
    { "The Report menu is on top", "it opens over the breakdown window instead of behind it." },
  } },
  { "1.2.11", {
    { "Meter windows stay where you put them", "windows placed side by side (Damage Done and Threat, for example) no longer drift apart after a reload or when a window grows or shrinks to fit its lines. Each window is now saved by its top-left corner however you moved it: dragging, snapping, layout mode or resizing. Windows snapped before this come back where you dropped them." },
  } },
  { "1.2.10", {
    { "OctoProcs is taken out for now", "it no longer loads and its section is gone from the options, until it is ready. Your settings for it are kept, so it comes back as you left it." },
  } },
  { "1.2.9", {
    { "Auction lengths are this server's", "the Sell tab and the Auctions options show 6 h / 24 h / 72 h, as OctoWoW's own auction window does (they said 2 / 8 / 24, but your auctions always lasted the right time). The longest \"time left\" now reads \"over 8 h\"." },
    { "Exact deposit", "the deposit shown when you post is now the same sum the game's own auction window uses, per stack." },
    { "/db opens the database window again", "search items, mobs, objects and quests. /db help lists the commands." },
  } },
  { "1.2.8", {
    { "World map zoom fixed", "the spot under your cursor now stays put as you zoom in and out with the mouse wheel. Before, the map slid away from where you pointed." },
  } },
  { "1.2.7", {
    { "Zoom into the world map (Magnify built in)", "the mouse wheel zooms in where your cursor is (up to 4x), drag moves the view, and a new zone starts whole again. Quest pins, your arrow and your party zoom along. Steps aside if you run Magnify, Cartographer or MetaMap. Shift + wheel (opacity) and Ctrl + wheel (size) still work." },
    { "World buff timers", "when a head is handed in (Onyxia, Nefarian, Rend, Hakkar), a bar counts down to the buff landing, with its name, where it lands and the seconds left, plus a popup and a sound. Shared with your guild and group so you see it anywhere. /wb lists the last drops. A new file: restart the game fully once." },
  } },
  { "1.2.6", {
    { "Built-in SuperCleveRoidMacros and pfQuest step aside properly", "with your own separate SuperCleveRoidMacros or pfQuest switched on, pfUI's built-in copy now reliably stays out of the way, so the two never run together (that broke loading for some). If both ever load anyway, the separate one is switched off and chat asks for a /reload." },
    { "A folded whisper window stays folded", "it no longer pops open by itself when a fight ends. Only a window that folded itself for the fight opens again." },
  } },
  { "1.2.5", {
    { "No more \"IndexActionSlot\" error flood", "if the built-in SuperCleveRoidMacros does not load fully on your PC, it now switches itself off instead of erroring on every action bar change, and says once in chat what went wrong. Please send that line to the pfUI Octo Discord so it can be fixed for good." },
  } },
  { "1.2.4", {
    { "st_timer for your macros", "the swing timer fills st_timer and st_timerOff (seconds left on each hand's swing) like SP_SwingTimer / ST_Swingtimer, so Slam macros work without them." },
    { "Resistances as numbers", "enemy tooltips show \"Fire 75 (20%)\" - the resistance and the share of your spells it takes. QoL > Tooltips > \"Resists shown as\" picks numbers only or % only." },
    { "Line up with the market, like Aux", "on the Sell tab, click an auction under \"On the auction house now\" and your price goes just under it (the same as your own). A picked item now starts under the cheapest price on the auction house; Auctions > \"A picked item's price\" keeps your last price instead." },
  } },
  { "1.2.3", {
    { "Kill Command and other procs in combat text", "the moment a reactive spell can be cast it pops over you like a crit, with the flash - Kill Command, Arcane Surge, Surprise Attack, Baited Shot, Lacerate and Hammer of Wrath now, as well as Overpower, Revenge, Riposte, Counterattack and Mongoose Bite. No bar needed with ClassicAPI or nampower. Gold for new setups; set your own in Combat Text > Messages and sounds > \"Reactive skills and procs\"." },
  } },
  { "1.2.2", {
    { "No more target frame error", "\"TargetFrame.lua:291: attempt to index global 'Turtle_ChallengesCache'\" over and over on every target change is gone. The game's challenge lookup now always finds its table, even when the game's own saved data for it is missing." },
  } },
  { "1.2.1", {
    { "OctoProcs looks", "our own art - wings, a crown, a light beam, a ring and a glow - tinted in each proc's colour, with a burst as a proc starts. Pick a look for all or for each proc, plus its place and colour. ProcDoc's options are all there (least / most opacity and size, pulse speed, top and side offsets, mute, timers) and more: art size, countdown size, only in a fight, edge glow width. The hard light columns and solid screen bands are gone." },
    { "Tanks are never told to hold off", "Meters > Threat > Label & warnings starts with \"I am a tank\" (Auto / Always / Never). Auto counts holding aggro, Defensive Stance, Bear Form, Righteous Fury, Rockbiter or a tank mark, and stance dancing in a fight no longer wakes the warnings." },
    { "Threat label clears the auras", "on a nameplate it sits above the aura row instead of on it." },
    { "Overpower / Revenge alerts back", "combat text switches on the nampower events they need itself." },
    { "Minimap pins stay inside a round map,", "with the built-in or a separate pfQuest." },
    { "World map menus", "no more overlap with ModernMapMarkers, and the menus stay on screen when Magnify zooms in." },
    { "Demo mode", "Wipe, Enrage, Healers out of mana and the other lasting events light up while on and turn off with a second click; no more \"interval is empty\" error." },
  } },
  { "1.2.0", {
    { "OctoRinse sees your talents", "with ClassicAPI the range check is the same one your action bar uses, so talents that lengthen your cures' range count. Without it, each cure's range comes from its spell, or you set it yourself." },
    { "OctoRinse looks", "pfUI Octo, Bars (rows filled with the debuff school's colour), Bright (strong colour, a border and bigger words), Compact and Icons. Plus a school-colour border, an out-of-range fade setting and a pulsing top row." },
    { "OctoProcs", "big pulsing alerts round your character the moment a proc is up, with the spell icon, a glow, a countdown and stacks, an optional screen-edge glow and a sound. Under CoolDownManager, /procs." },
    { "Every nampower setting", "Settings > nampower has all of nampower's own options (spell queue, channels, safety, chat bubbles and more), each with its default and a reset." },
  } },
  { "1.1.99", {
    { "SuperCleveRoidMacros built in", "the newest SuperCleveRoidMacros now comes inside pfUI, nothing else to install. It needs ClassicAPI 1.15.8 or newer (the Octo DLL Installer puts it in). Your SCRM settings carry over." },
    { "Takes over your separate copy", "if you had SuperCleveRoidMacros installed, pfUI switches it off for your next login and says so in chat. Tick it again in the add-on list to keep yours - pfUI leaves it alone after that." },
    { "Conditional macros show right on the bars", "pfUI's action bars now leave macros to SuperCleveRoidMacros, so a button shows the spell, icon and cooldown it will really cast instead of the macro's first spell." },
  } },
  { "1.1.98", {
    { "Your monitor's Hz", "pick your refresh rate (only the ones your screen offers), vsync and triple buffering in Settings > Performance. Many games stay at 60 Hz on a faster screen until this is set. Apply restarts the graphics for a second and puts everything back by itself in 15 s unless you keep it." },
    { "Frame cap", "1.12 has no frame cap of its own, so the page copies the DXVK line for you: a Steam / Lutris launch option, or one line for dxvk.conf. G-Sync / FreeSync screens get a cap 3 under the Hz." },
    { "Playing on Linux", "one switch for Wine / Proton / Lutris players: no forced wait for the graphics card (more frames), a smooth hardware mouse pointer, lighter effects in dungeons too and the memory ceiling on. Your own settings come back when you switch it off. It also shows which DLLs really loaded." },
    { "Fewer far-away players (PerfBoost)", "with the PerfBoost DLL, set how far players, pets and trash are drawn, in and out of combat. Three ready looks, and PvP-flagged or raid-marked players can always stay drawn. The biggest FPS gain in raids and cities." },
  } },
  { "1.1.97", {
    { "Raid chat window", "opens by itself when you join a raid and shows only what matters in a fight: raid chat and raid warnings, with the leader's and assists' calls standing out and the \"+\" answers gathered under each call as one line of names." },
    { "Taunts and overaggro", "who taunted what (SuperWoW), resisted / missed / dodged / parried taunts in red, and a red OVERAGGRO line when a boss turns to someone who isn't tanking it." },
    { "Healer mana after a fight", "every healer's mana, lowest first, with the raid average." },
    { "Loot", "the master looter's links tagged [ML] and epic loot the raid receives. Links and names click as in any chat, and a box at the bottom talks to the raid." },
    { "Quiet chat in raids", "no General / Trade / LFG / World in your other chat windows while you raid, back the moment you leave or click Q. Chat & Panels > Raid chat, /raidchat test to try it." },
  } },
  { "1.1.96", {
    { "The demo uses your whole action bar", "every spell, item and macro on your bars gets used in turn with its own cooldown sweep, every slot shows the global cooldown, and your trinkets go on cooldown too." },
    { "Resses like a real raid", "after a wipe nobody stands up at once. Ressers get up first, each res has its cast bar and the res icon shows on the one being ressed, and the next pull waits until everyone is up." },
    { "The boss turns for real", "after an overthreat (yours or a raider's), target of target shows whoever has aggro, and the boss hits them until the tank taunts it back." },
    { "A live threat meter all demo long", "a threat cycle runs on its own (a DoT player's countdown, your overthreat, a melee pull), and the meter keeps the last fight between pulls." },
    { "Meter windows never stay stuck small", "a window saved while fitted to its lines grows back to show everyone." },
  } },
  { "1.1.95", {
    { "Smooth bars in every meter", "with ClassicAPI the bars glide to their new size in the game client itself. It's smoother and costs the add-on nothing. A bar that changes player jumps at once." },
    { "Neat columns everywhere", "per second, total and % in columns of their own that line up down every window, with small headings. A narrow window drops columns before it squashes names." },
    { "Windows fit their lines", "no empty space under the last bar." },
    { "Clearer threat window", "the DoTs line names whose DoTs pull next (\"DoTs Gul'dan in 7 s\"), the title shows your own %, \"You hold aggro\" while you tank, calm top lines with their own colour options, and a preview that always matches your meter." },
  } },
  { "1.1.94", {
    { "Threat is back inside Meters", "a big \"Damage, healing & more | Threat\" switch at the top of every Meters page, and a working preview of your threat window." },
    { "% of the pull point", "each player's % is of where THEY pull aggro (110% of the tank in melee, 130% at range). The one the boss is on is first, on \"Aggro\". Nobody else ever reaches 100% until the boss turns to them." },
    { "Everyone's DoT countdown", "every player's line shows their own seconds before they pull, and a \"Next\" line names who pulls next, so a raid leader sees it too. Your own \"DoTs +22.5k\" line shows what your DoTs still add." },
    { "Clear and readable", "info lines in their own colours (DoTs purple, next amber), words that shrink to fit, and the target's full name, never cut." },
    { "Whispers", "a green +N on the bar for new messages, and unfolding goes to the oldest new one first." },
    { "Power dots everywhere", "every section with an on/off dot keeps it while its module is off, so you can always switch it back on." },
  } },
  { "1.1.93", {
    { "OctoThreat, its own section", "your threat window with a live preview, locked to threat so its menu can't switch it away, plus every threat setting on two pages (Threat window / Label & warnings)." },
    { "\"DoTs pull in 4 s\" in the threat window", "the pull line turns red with the countdown, and your line shows the threat still on its way as a lighter part." },
    { "Steadier raid threat", "between the server's answers nobody jumps above the tank on a guess. Only the server's own numbers can put someone past the tank." },
    { "Demo events", "an Events menu on the demo bar and buttons on the Demo mode page: Overthreat, DoTs pull aggro, Tank dies, Raid-wide damage, Big cast, Debuffs to cure, Enrage, Healers out of mana, Someone dies, Battle res, Res everyone, Wipe, Kill the boss." },
    { "Whispers in one window", "a tab per person instead of a window each." },
  } },
  { "1.1.92", {
    { "Demo mode never gets stuck", "if a demo can't start, everything is put back at once and chat says why. Stop always finishes, so you can start again without a reload. Before, a demo that failed to start could leave Stop doing nothing until you reloaded." },
  } },
  { "1.1.91", {
    { "Threat on the way, for warlocks and every DoT class", "the threat label shows where your DoTs and the spell you are casting will take you (\"72% > 88%\"), like incoming heals on a health bar." },
    { "\"DoTs pull in 4 s\"", "a countdown before you pull aggro. \"DoTs pull\" means the DoTs already ticking will do it even if you stop now, so move to the tank. \"Aggro in\" means your current pace gets you there." },
    { "A popup before you pull", "\"DOTS PULL AGGRO IN 3 s\" with the threat sound, and the threat window's pull line shows the countdown too. Settings on Meters > Threat > What is on the way." },
  } },
  { "1.1.90", {
    { "Right-click to attach works with other add-ons", "with the mailbox open, right-clicking an item in your bags adds it to the Send list and opens the Send tab, even when another add-on (like _LazyPig) changes what a bag click does." },
    { "Read every auction is lighter", "a full read only notes prices, no longer redraws the list after every page and takes a short pause between pages, so the game stays smooth on a busy auction house." },
    { "Nameplate spell icons can be turned off", "text on nameplates has its own Spell icon setting (Combat Text > Nameplates > Look). The scroll areas' setting never reached it." },
    { "Quest pins stay inside a round minimap", "pfQuest's pins follow the map's shape (round, diamond, octagon...) instead of spilling over the edge." },
  } },
  { "1.1.89", {
    { "Demos play your own class", "every demo but AFK casts your class's real spells, DoTs, cooldowns and procs, so your action bars, OctoDoTs, cooldown bars, combat text and meters show what you would really see. The Demo Mode page lists the spells it uses." },
    { "Party frames always join in", "if your settings hide the party frames (hidden in raids, raid frames for groups, placed off screen), the demo shows them anyway and says once in chat why they were hidden." },
    { "Every module plays its own test", "cooldown bars, OctoTotems, consumables and the rest cycle through their samples while a demo runs, and the AFK demo has its own AFK screen." },
    { "Crash fix", "a disconnect while a demo was running could crash the game (#132). The demo now cleans up when you leave the world, before the game frees its unit data." },
  } },
  { "1.1.88", {
    { "Every demo is in", "Demo Mode now has its own highlighted row in the sidebar (under More, above Add-ons) and tiles on the Quality of Life page. Six demos, each looping until you press Stop:" },
    { "Nothing a demo does reaches anyone: no raid messages or threat requ...", "Nothing a demo does reaches anyone: no raid messages or threat requests are sent while you are not really in a group." },
  } },
  { "1.1.87", {
    { "Demo mode (raid)", "Quality of Life > Demo mode, or /demo. A pretend 40-player raid on your own frames with all your settings: raid and party frames, a boss on your target frame with its crest, cast bar and abilities, debuffs to cure, raid warnings, meters and combat text. It loops trash, boss, kill or wipe and rest until you stop it. The bar at the top has Pause, speed (0.5x-4x), Next, Edit and Stop. Nothing real happens and Stop puts everything back; a real fight stops it. Needs a full client restart (new files). Dungeon, target dummy, PvP, AFK and showcase demos come next." },
  } },
  { "1.1.86", {
    { "Unit Frames options sorted like ElvUI / EllesmereUI", "the tabs are now the parts of the frame, in order - Frame, Health, Power, Text, Portrait, Buffs & debuffs, Icons & art, Raid layout - and everything every frame shares sits on one gold All frames tab at the end. Names are written in full." },
    { "Change together", "tick Player, Target, Focus (or any frame) under the tabs and every change you make goes to them too. Not their position; it stops when you log out." },
    { "Every dragon and crest as pictures", "Icons & art > Elite, rare and boss art shows every badge as a tile - off, the word, four dragons (Elite Overlay plus three of the game's own) and every crest. Each frame can have its own." },
  } },
  { "1.1.85", {
    { "Faded parts in the unit frame preview", "the elite badge, raid mark, leader, loot and PvP icons now show faded on the Unit Frames preview while they are switched off. Click one to go straight to the setting that turns it on - the faded crest takes you to the Elite Overlay dragons." },
  } },
  { "1.1.84", {
    { "Elite Overlay dragons", "Shagu's pfUI-eliteoverlay is built in. Pick \"Dragons (Elite Overlay)\" under Unit Frames > Frames > Class and status: gold dragons wrap elites and rare elites, red ones world bosses, grey ones rares, on the side \"Badge at\" picks. Needs a full client restart for the new pictures." },
  } },
  { "1.1.83", {
    { "No more game heal numbers over heads", "SuperWoW's own heal numbers could come back on after a client start and float over every player you healed. While pfUI Octo's combat text is on they are now kept off at every login (unless you switched them on yourself on the Combat Text page)." },
    { "Meter windows move on their own", "windows snapped side by side no longer drag each other along. \"Snapped windows move together\" is off by default (Meters > Data) - snapping into line on drop stays." },
  } },
  { "1.1.82", {
    { "Right names on the map", "hovering a party or raid member's dot on the world map could show a player from a group you were in before - the name was read once and kept. It is now read fresh on every hover." },
  } },
  { "1.1.81", {
    { "Moved frames stay put", "a game window you picked with Move anything (the quest log, for example) went back to the game's own place whenever the game laid its windows out. Its saved place now goes back on after that, as it opens, and once more a moment later." },
  } },
  { "1.1.80", {
    { "Whisper windows really open now", "a new window was never given a place on the screen (the game counts a new window as already shown), so nothing appeared - /whispers test included. Each window now starts hidden, gets its place, then shows." },
  } },
  { "1.1.79", {
    { "Whisper windows fixed", "the window per person broke for anyone you had whispered before - its saved conversation went in before the window had a font, which the game refuses. Each window now gets its font the moment it is made." },
  } },
  { "1.1.78", {
    { "ItemRack button shows what you wear", "the set button and the minimap button show a set's picture only while that set is worn exactly. Swap a piece by hand (or wear no set) and they show your worn gear instead, updated every time your gear changes." },
  } },
}
